<main>
    <section class="section section--primary"><div class="container"><div class="section__title"><h1>Lo que dicen nuestros clientes</h1><p class="section__title-text">Las empresas confían en RCN Sistemas para su transformación digital.</p></div></div></section>
    <section class="section"><div class="container"><div class="grid"><?php if ($testimonials): ?><?php foreach ($testimonials as $testimonial): ?><article class="card testimonial-card"><i class="fas fa-quote-left testimonial-card__quote"></i><div class="testimonial-card__stars"><?php for ($index = 0; $index < $testimonial->rating; $index++): ?><i class="fas fa-star"></i><?php endfor; ?></div><p class="testimonial-card__text">“<?php echo htmlspecialchars($testimonial->message, ENT_QUOTES, 'UTF-8'); ?>”</p><div class="testimonial-card__author"><div class="testimonial-card__avatar"><?php echo htmlspecialchars(substr($testimonial->name, 0, 1), ENT_QUOTES, 'UTF-8'); ?></div><div class="testimonial-card__author-info"><h3 class="testimonial-card__author-name"><?php echo htmlspecialchars($testimonial->name, ENT_QUOTES, 'UTF-8'); ?></h3><p class="testimonial-card__author-meta"><?php echo $testimonial->date ? date('d M, Y', strtotime($testimonial->date)) : ''; ?></p></div></div></article><?php endforeach; ?><?php else: ?><p class="section__title-text">Aún no hay testimoniales. ¡Sé el primero en dejar uno!</p><?php endif; ?></div></div></section>
    <section class="section section--gray"><div class="container"><div class="section__title"><h2>Déjanos tu opinión</h2><p class="section__title-text">Tu feedback nos ayuda a mejorar cada día.</p></div><div class="card form-card testimonial-form-card"><?php if ($success): ?><div class="alert alert--success"><i class="fas fa-check-circle alert__icon"></i><p><?php echo htmlspecialchars($success, ENT_QUOTES, 'UTF-8'); ?></p></div><?php else: ?><?php if ($error): ?><div class="alert alert--error"><?php echo htmlspecialchars($error, ENT_QUOTES, 'UTF-8'); ?></div><?php endif; ?><form method="post" class="form"><div class="form__group"><label for="name" class="form__label">Tu nombre *</label><input type="text" id="name" name="name" class="form__input" required></div><div class="form__group"><label for="rating" class="form__label">Calificación *</label><select id="rating" name="rating" class="form__select" required><option value="5">5 estrellas - Excelente</option><option value="4">4 estrellas - Muy bueno</option><option value="3">3 estrellas - Bueno</option><option value="2">2 estrellas - Regular</option><option value="1">1 estrella - Pobre</option></select></div><div class="form__group"><label for="message" class="form__label">Tu comentario *</label><textarea id="message" name="message" class="form__textarea" rows="4" required></textarea></div><?php echo $csrf; ?><button type="submit" class="btn">Enviar testimonial</button></form><?php endif; ?></div></div></section>
</main>
